// Go's default: a buffered channel IS a ring buffer (hchan: dataqsiz, sendx,
// recvx) plus wait queues. This is what almost every Go program should use:
ch := make(chan Job, 256)   // fixed capacity, allocated once, never grows

// Hand-written SPSC ring for a fixed, allocation-free hot path (e.g. audio):
type ring struct {
    buf   [1024]float32        // power of two; a static array, no allocation
    mask  uint64
    _     [64]byte             // pad head away from tail (different cache lines)
    head  atomic.Uint64        // producer-owned
    _     [64]byte
    tail  atomic.Uint64        // consumer-owned
}
func (r *ring) push(v float32) bool {
    h := r.head.Load()
    if h - r.tail.Load() == 1024 { return false }
    r.buf[h & r.mask] = v
    r.head.Store(h + 1)        // sequentially consistent in Go: publishes the item
    return true
}
